import { useState } from 'react';
import { JxButton, JxTagInput } from '@jinx-ui/react';

export interface ArticleTagsFieldProps {
  value?: string[];
  defaultValue?: string[];
  onChange?: (tags: string[]) => void;
  label?: string;
  placeholder?: string;
  maxTags?: number;
}

export default function ArticleTagsField({
  value,
  defaultValue = [],
  onChange,
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  maxTags,
}: ArticleTagsFieldProps) {
  const [internal, setInternal] = useState<string[]>(defaultValue);
  const tags = value ?? internal;

  const commit = (next: string[]) => {
    const normalized = next
      .map((tag) => tag.trim())
      .filter((tag, index, all) => tag.length > 0 && all.indexOf(tag) === index);
    const limited =
      typeof maxTags === 'number' ? normalized.slice(0, maxTags) : normalized;

    if (value === undefined) setInternal(limited);
    onChange?.(limited);
  };

  const remove = (tag: string) => commit(tags.filter((item) => item !== tag));

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-2)',
      }}
    >
      <JxTagInput
        label={label}
        placeholder={placeholder}
        value={tags}
        onValueChange={commit}
      />

      {tags.length > 0 && (
        <ul
          aria-label="Выбранные теги"
          style={{
            display: 'flex',
            flexWrap: 'wrap',
            gap: 'var(--jx-space-2)',
            margin: 0,
            padding: 0,
            listStyle: 'none',
          }}
        >
          {tags.map((tag) => (
            <li key={tag}>
              <JxButton
                variant="ghost"
                size="sm"
                onClick={() => remove(tag)}
                aria-label={`Удалить тег ${tag}`}
              >
                {tag} ✕
              </JxButton>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

